"""Casos fictícios de troubleshooting usados para gerar o PDF da base de conhecimento."""


def c(id, titulo, cat, sev, so, impacto, sintomas, causa, diag, solucao, validacao, prevencao, escal):
    return dict(id=id, titulo=titulo, cat=cat, sev=sev, so=so, impacto=impacto, sintomas=sintomas, causa=causa,
                diag=diag, solucao=solucao, validacao=validacao, prevencao=prevencao, escal=escal)


